import hashlib

SAMPLES = {
    "5f4dcc3b5aa765d61d8327deb882cf99": "password",
    "5baa61e4c9b93f3f0682250b6cf8331b7ee68fd8": "password",
    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855": "",
}

LENGTHS = {32: "MD5", 40: "SHA-1", 64: "SHA-256", 128: "SHA-512"}

def identify(digest):
    return LENGTHS.get(len(digest), "unknown")

def verify(candidate, digest, algo):
    name = {"MD5": "md5", "SHA-1": "sha1", "SHA-256": "sha256", "SHA-512": "sha512"}[algo]
    h = hashlib.new(name)
    h.update(candidate.encode("utf-8"))
    return h.hexdigest() == digest

for dg, pw in SAMPLES.items():
    algo = identify(dg)
    print(dg[:16], "... ->", algo, "| verifies:", verify(pw, dg, algo))

# Bonus: why unsalted fast hashes are weak for passwords
print("sha256('password') =", hashlib.sha256(b"password").hexdigest())

