import math

POOLS = {"lowercase": 26, "uppercase": 26, "digits": 10, "symbols": 32}

def charset_size(used):
    return sum(POOLS[c] for c in used)

def entropy_bits(password, used):
    return len(password) * math.log2(charset_size(used))

def grade(bits):
    if bits < 40:
        return "Weak"
    if bits < 60:
        return "Fair"
    if bits < 80:
        return "Strong"
    return "Excellent"

tests = [("Tr0ub4dor&3", ["lowercase", "uppercase", "digits", "symbols"]),
         ("correct horse battery staple", ["lowercase"])]
for pw, used in tests:
    b = entropy_bits(pw, used)
    print(repr(pw), "->", round(b, 1), "bits:", grade(b))

SAMPLE = ("Host: 10.0.0.5 ()\tPorts: 22/open/tcp//ssh///, "
          "80/open/tcp//http///, 443/filtered/tcp//https///, "
          "3389/open/tcp//ms-wbt-server///, 3306/closed/tcp//mysql///\n")
RISKY = {"telnet": 23, "ms-wbt-server": 3389, "mysql": 3306}

def parse_gnmap(line):
    ports = {}
    portlist = line.split("Ports:", 1)[1]
    for entry in portlist.split(","):
        fields = entry.strip().split("/")
        if len(fields) >= 5:
            port, state, service = fields[0], fields[1], fields[4]
            ports[int(port)] = (state, service)
    return ports

def assess(ports):
    open_ports = {p: s for p, (st, s) in ports.items() if st == "open"}
    filtered = [p for p, (st, _s) in ports.items() if st == "filtered"]
    print("Open ports:", open_ports)
    print("Filtered ports:", filtered)
    for p, svc in open_ports.items():
        if svc in RISKY:
            print("RISKY EXPOSURE: port", p, "running", svc, "- restrict or remove")

assess(parse_gnmap(SAMPLE))

