import json

POLICY = {
    "Version": "2012-10-17",
    "Statement": [
        {"Effect": "Allow", "Action": "s3:GetObject", "Resource": "arn:aws:s3:::reports/*"},
        {"Effect": "Allow", "Action": "*", "Resource": "*"},
        {"Effect": "Allow", "Action": "ec2:Describe*", "Resource": "*"}
    ]
}

def as_list(x):
    return x if isinstance(x, list) else [x]

def review(policy):
    findings = []
    for i, st in enumerate(policy["Statement"]):
        if st.get("Effect") != "Allow":
            continue
        for act in as_list(st.get("Action", [])):
            if act == "*":
                findings.append((i, "HIGH", "Wildcard Action '*' grants every API action - scope to explicit actions"))
            elif act.endswith(":*"):
                findings.append((i, "MEDIUM", "Broad action prefix '%s' - narrow to needed verbs" % act))
        for res in as_list(st.get("Resource", [])):
            if res == "*":
                findings.append((i, "HIGH", "Wildcard Resource '*' - restrict to explicit ARNs"))
        acts = " ".join(as_list(st.get("Action", []))).lower()
        if any(w in acts for w in ("delete", "put", "write", "*")) and "Condition" not in st:
            findings.append((i, "MEDIUM", "Write/delete-level action with no Condition - add source-IP, MFA, or time conditions"))
    return findings

for f in review(POLICY):
    print(f)
print("\nLeast-privilege rewrite: grant only the named actions on the named ARNs, nothing else.")

from datetime import datetime

EVENTS = [
    {"timestamp": "2026-10-06T14:22:10", "source": "EDR", "event": "ransomware note dropped"},
    {"timestamp": "2026-10-06 13:58:02", "source": "firewall", "event": "C2 beacon to 203.0.113.77"},
    {"timestamp": "10/06/2026 13:41:55", "source": "proxy", "event": "user clicked phishing link"},
    {"timestamp": "2026-10-06T14:05:44", "source": "EDR", "event": "SMB lateral movement"},
]

def parse_ts(ts):
    try:
        return datetime.fromisoformat(ts)
    except ValueError:
        return datetime.strptime(ts, "%m/%d/%Y %H:%M:%S")

def build_timeline(events):
    stamped = [dict(e, _dt=parse_ts(e["timestamp"])) for e in events]
    ordered = sorted(stamped, key=lambda e: e["_dt"])
    out = []
    for e in ordered:
        e["timestamp"] = e.pop("_dt").isoformat(sep=" ")
        out.append(e)
    return out

for e in build_timeline(EVENTS):
    print(e["timestamp"], "|", e["source"], "|", e["event"])
print("\nNarrative: phish click -> C2 beacon -> lateral movement -> ransom note.")
